INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N034-01','CN0275','S034-01','建成装置','公司简介','2007成立、2014股权转让后转危废，官网自述70亩、3.5万吨废催化剂、4万吨废矿物油、8万吨废焦油、11.6万只废包装桶；其他处理规模不计催化剂。经营许可具体有效期待核。','WEB_COMPANY','公开正文或摘录，非原件归档','2026-11-27');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N034-02','CN0275','S034-02','生产与污水站线索','生产车间检索摘录','废剂焙烧、溶浸、过滤、置换回收稀贵金属；另列综合车间及污水处理站栏目。未公开水处理单元与工艺水量，不能以生产流程推断污水膜；全文打开超时。','WEB_COMPANY','公开正文或摘录，非原件归档','2026-11-27');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N034-03','CN0275','S034-04','外部废剂处置报价','成交表','2026-11-18转载成交供应商甘肃银泰，响应报价190000元，未披露吨数、含税成交价栏未见具体值；不认定19万元实际结算，不当作吨水或废盐处置费用。','WEB_SECONDARY','公开正文或摘录，非原件归档','2026-11-27');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N034-04','CN0276','S034-05','建设期与规划产品','2026-10-28正文','一期低碳烃氧化催化剂生产线主体完工、拟验收，计划2026-12中旬单机调试/试生产；二期催化剂一体化回收；规划1000/500/500t/a三类产品。未证明项目已生产或环保验收。','WEB_SECONDARY','公开正文或摘录，非原件归档','2026-11-27');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N034-05','CN0277','S034-08','前期工程线索','项目基本信息与建设内容','平台报总投资2.495亿元、用地53333m²、建筑32500m²、预计2027Q1至2028Q4，非政府正式设计或实际施工；业主脱敏不猜。','WEB_SECONDARY','公开正文或摘录，非原件归档','2026-11-27');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N034-06','CN0278','S034-09','项目用电及签约','报道正文','2025兰洽会签约项目、临时施工供电方案；非投产证明。2025-08拟审批仅标题待原文。','WEB_SECONDARY','公开正文或摘录，非原件归档','2026-11-27');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N034-07','CN0262','S034-11','旧许可证分项','附件第1项','2021许可22000t/a干基，HW50 7000+3000，HW46 12000；2024增加HW50 8000t/a及30小类；2026许可仍总30000但分项调整。不同口径不相加，不代表实际处理量。','WEB_PRIMARY','公开正文或摘录，非原件归档','2026-11-27');
